/* Per-call instruction cost of calloc(n, 1) against malloc(n) under one glibc,
 * for the allocation a design-B shell makes on a collector-freelist miss
 * (40 bytes at 16-byte alignment, which Rust's System allocator serves with
 * malloc/calloc). Three heap states, each run as its own process so the
 * heaps do not share history:
 *   growth: N fresh blocks, none freed (an insert arm's shells);
 *   same:   as mixed, but the freed block is 40 bytes, so tcache holds the size;
 *   mixed:  each step frees one earlier short-lived 24-byte block first, so
 *           the bins and tcache are warm (an arm that drops probe strings).
 * usage: allocpc <calloc|malloc> <growth|mixed|same> <N>
 * Run under: valgrind --tool=callgrind --toggle-collect=one */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void *volatile sink;

__attribute__((noinline)) void *one(int use_calloc, size_t n) {
    return use_calloc ? calloc(n, 1) : malloc(n);
}

__attribute__((noinline)) void work(int use_calloc, int mixed, long n, void **keep, void **tmp) {
    for (long i = 0; i < n; i++) {
        if (mixed) {
            free(tmp[i]);
        }
        keep[i] = one(use_calloc, 40);
    }
}

int main(int argc, char **argv) {
    if (argc != 4) return 2;
    int use_calloc = strcmp(argv[1], "calloc") == 0;
    int mixed = strcmp(argv[2], "growth") != 0; size_t tsz = strcmp(argv[2], "same") == 0 ? 40 : 24;
    long n = atol(argv[3]);
    void **keep = malloc(sizeof(void *) * n);
    void **tmp = malloc(sizeof(void *) * n);
    for (long i = 0; i < n; i++) tmp[i] = mixed ? malloc(tsz) : NULL;
    work(use_calloc, mixed, n, keep, tmp);
    sink = keep[n - 1];
    printf("ok %s %s %ld\n", argv[1], argv[2], n);
    return 0;
}
